package com.pousadamarealta;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;

import java.net.http.HttpResponse;

import static org.junit.jupiter.api.Assertions.*;

class ReservationFlowIT extends IntegrationTest {

    @Test
    void testCompleteReservationFlow() throws Exception {
        String reservationJson = """
            {
                "roomNumber": "101",
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "12345678901",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
        """;

        HttpResponse<String> createResponse = post("/reservations", reservationJson);
        assertEquals(201, createResponse.statusCode());

        JsonNode reservation = objectMapper.readTree(createResponse.body());
        long reservationId = reservation.get("id").asLong();
        assertEquals("PENDING", reservation.get("status").asText());
        assertEquals(2, reservation.get("nights").asInt());
        assertEquals("499.80", reservation.get("subtotal").asText());
        assertEquals("0.00", reservation.get("discount").asText());
        assertEquals("499.80", reservation.get("total").asText());

        HttpResponse<String> confirmResponse = post("/reservations/" + reservationId + "/confirmation", "");
        assertEquals(200, confirmResponse.statusCode());

        JsonNode confirmed = objectMapper.readTree(confirmResponse.body());
        assertEquals("CONFIRMED", confirmed.get("status").asText());
        assertEquals("499.80", confirmed.get("amountPaid").asText());

        HttpResponse<String> messagesResponse = get("/messages");
        JsonNode messages = objectMapper.readTree(messagesResponse.body());
        assertTrue(messages.isArray());
        assertTrue(messages.size() > 0);

        JsonNode message = messages.get(0);
        assertEquals("EMAIL", message.get("channel").asText());
        assertEquals("joao@example.com", message.get("to").asText());
        assertEquals("Reserva confirmada - Pousada Maré Alta", message.get("subject").asText());

        HttpResponse<String> checkInResponse = post("/reservations/" + reservationId + "/check-in", "");
        assertEquals(200, checkInResponse.statusCode());

        JsonNode checkedIn = objectMapper.readTree(checkInResponse.body());
        assertEquals("CHECKED_IN", checkedIn.get("status").asText());

        HttpResponse<String> checkOutResponse = post("/reservations/" + reservationId + "/check-out", "");
        assertEquals(200, checkOutResponse.statusCode());

        JsonNode document = objectMapper.readTree(checkOutResponse.body());
        assertEquals("Comprovante de reserva", document.get("title").asText());
        assertEquals(reservationId, document.get("reservationId").asLong());
        assertEquals("João Silva", document.get("guestName").asText());
    }

    @Test
    void testNonRefundableReservation() throws Exception {
        String reservationJson = """
            {
                "roomNumber": "201",
                "guestName": "Maria Santos",
                "guestEmail": "maria@example.com",
                "guestCpf": "98765432109",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "NON_REFUNDABLE"
            }
        """;

        HttpResponse<String> createResponse = post("/reservations", reservationJson);
        assertEquals(201, createResponse.statusCode());

        JsonNode reservation = objectMapper.readTree(createResponse.body());
        long reservationId = reservation.get("id").asLong();

        assertEquals("779.80", reservation.get("subtotal").asText());
        assertEquals("116.97", reservation.get("discount").asText());
        assertEquals("662.83", reservation.get("total").asText());

        post("/reservations/" + reservationId + "/confirmation", "");

        HttpResponse<String> cancelResponse = post("/reservations/" + reservationId + "/cancellation", "");
        JsonNode cancelled = objectMapper.readTree(cancelResponse.body());

        assertEquals("CANCELLED", cancelled.get("status").asText());
        assertEquals("0.00", cancelled.get("refund").asText());
    }

    @Test
    void testHighSeasonPricing() throws Exception {
        String reservationJson = """
            {
                "roomNumber": "101",
                "guestName": "Carlos Lima",
                "guestEmail": "carlos@example.com",
                "guestCpf": "11122233344",
                "checkIn": "2027-07-10",
                "checkOut": "2027-07-12",
                "guests": 1,
                "ratePlan": "STANDARD"
            }
        """;

        HttpResponse<String> createResponse = post("/reservations", reservationJson);
        JsonNode reservation = objectMapper.readTree(createResponse.body());

        assertEquals("599.76", reservation.get("subtotal").asText());
        assertEquals("599.76", reservation.get("total").asText());
